"""Generated by solo-to-scale; edit `templates/tools/tests/test_heartbeat.py` in the plugin, then run upgrade.

Heartbeats and budgets: the run gate, one ticket per run, the cost log, the 80% warning and the 100% stop,
against a fake GitHub.
"""
from __future__ import annotations

import json
import sys
import urllib.parse
from pathlib import Path

import pytest

TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
sys.path.insert(0, str(Path(__file__).resolve().parent))
import approval  # noqa: E402
import heartbeat  # noqa: E402
import tickets  # noqa: E402
from test_tickets import REPO, FakeGitHub  # noqa: E402

MONTH = "2026-11"
NOW = 1_800_000_000.0


class Fake(FakeGitHub):
    """Adds comment pages and the comment author, like the real API."""

    def __init__(self) -> None:
        super().__init__()
        self.author = "acme-bot"

    def __call__(self, *args: str, payload: dict | None = None):
        path, _, query = args[0].removeprefix(f"repos/{REPO}/").partition("?")
        parts = path.split("/")
        method = args[args.index("-X") + 1] if "-X" in args else "GET"
        if len(parts) == 3 and parts[0] == "issues" and parts[2] == "comments":
            n = int(parts[1])
            if method == "POST":
                self.comments[n].append({"user": {"login": self.author}, "body": payload["body"], "created_at": "x"})
                return {}
            q = urllib.parse.parse_qs(query)
            page, size = int(q.get("page", ["1"])[0]), int(q.get("per_page", ["30"])[0])
            return self.comments[n][(page - 1) * size: page * size]
        return super().__call__(*args, payload=payload)


