@pytest.fixture()
def fake(monkeypatch: pytest.MonkeyPatch) -> Fake:
    f = Fake()
    monkeypatch.setattr(tickets, "gh", f)
    monkeypatch.setattr(approval, "gh", f)
    monkeypatch.delenv("GITHUB_REPOSITORY", raising=False)
    return f


def run(root: Path, *args: str) -> int:
    extra = ["--now", str(NOW)] if args[0] == "start" else []
    return heartbeat.main([*args, *extra, "--root", str(root), "--month", MONTH])


def ticket(f: Fake, role: str, title: str = "t", blockers: list[int] | None = None) -> int:
    body = tickets.ticket_body(role, "goal", "", "", None, blockers or [], "product")
    return f.make(title, body, ["ticket", f"role:{role}"] + (["blocked"] if blockers else []))


def spend(root: Path, role: str, usd: float) -> int:
    return run(root, "end", role, "--usd", str(usd))


def test_off_unbudgeted_and_spent_roles_never_claim(root, fake, capsys):
    for role in ("growth", "research"):
        ticket(fake, role)
        assert run(root, "start", role) == heartbeat.STOP
    assert "heartbeat is off" in capsys.readouterr().out
    n = ticket(fake, "engineer")
    assert spend(root, "engineer", 10.0) == heartbeat.OK
    assert run(root, "start", "engineer") == heartbeat.STOP
    assert "budget spent" in capsys.readouterr().out
    assert "claimed" not in fake.names(n) and not any(r.startswith("refs/claims") for r in fake.refs)
    assert not any(r.startswith("refs/heartbeats") for r in fake.refs), "a refused run holds no lock"


def test_a_run_claims_one_ready_ticket_and_a_second_run_stops(root, fake, capsys):
    blocker = ticket(fake, "architect")
    ticket(fake, "engineer", "Blocked one", blockers=[blocker])
    first, second = ticket(fake, "engineer", "First"), ticket(fake, "engineer", "Second")
    assert run(root, "start", "engineer") == heartbeat.OK
    assert f"work on #{first}: First" in capsys.readouterr().out
    assert "claimed" in fake.names(first) and "claimed" not in fake.names(second)
    assert run(root, "start", "engineer") == heartbeat.STOP, "one run per role at a time"
    assert "another role:engineer run is active" in capsys.readouterr().out
    assert run(root, "end", "engineer", "--ticket", str(first), "--usd", "1.5") == heartbeat.OK
    assert "still claimed by role:engineer" in capsys.readouterr().out
    assert run(root, "start", "engineer") == heartbeat.OK
    assert f"resume #{first}" in capsys.readouterr().out, "its own claim comes before a new one"
    assert "claimed" not in fake.names(second)


def test_a_stale_run_lock_is_taken_over(root, fake):
    ticket(fake, "qa")
    assert heartbeat.take_run(tickets.Hub(REPO), "qa", NOW - 7 * 3600)
    assert run(root, "start", "qa") == heartbeat.OK


def test_nothing_ready_frees_the_lock(root, fake, capsys):
    ticket(fake, "qa")
    assert run(root, "start", "engineer") == heartbeat.IDLE
    assert "nothing to do" in capsys.readouterr().out
    assert not fake.refs


def test_costs_sum_across_pages_and_only_this_month(root, fake, capsys):
    for _ in range(105):
        assert spend(root, "product", 0.05) == heartbeat.OK
    log = next(i for i in fake.issues.values() if "cost-log" in fake.names(i["number"]))
    fake.comments[log["number"]].append({"body": heartbeat.cost_entry("product", 99, "2026-10", "reported", None, ""),
                                         "created_at": "x"})
    fake.comments[log["number"]].append({"body": '<!-- s2s:cost {"role": "product", "usd": -50, "month": "2026-11"} -->'})
    capsys.readouterr()
    assert run(root, "costs") == heartbeat.OK
    assert "product: $5.25 of $10.00 (52%)" in capsys.readouterr().out
    with pytest.raises(SystemExit):
        spend(root, "product", -1)


def test_warning_at_80_and_stop_at_100_fire_once(root, fake, capsys):
    n = ticket(fake, "qa")
    assert spend(root, "qa", 7.0) == heartbeat.OK and "budget" not in capsys.readouterr().out.split("\n", 1)[1]
    assert run(root, "end", "qa", "--ticket", str(n), "--usd", "1.5") == heartbeat.OK
    assert "budget over 80%" in capsys.readouterr().out
    assert any("budget warning" in c["body"] for c in fake.comments[n])
    assert spend(root, "qa", 0.1) == heartbeat.OK and "budget" not in capsys.readouterr().out.split("\n", 1)[1]
    assert spend(root, "qa", 2.0) == heartbeat.OK and "budget spent" in capsys.readouterr().out
    assert run(root, "start", "qa") == heartbeat.STOP
    assert run(root, "start", "qa") == heartbeat.STOP
    requests = [i for i in fake.issues.values() if "gate:budget" in fake.names(i["number"])]
    assert len(requests) == 1, "one budget request per role and month"
    assert f"**Scope:** heartbeat:qa:{MONTH}" in requests[0]["body"]


def test_only_the_founders_approve_adds_budget(root, fake):
    ticket(fake, "qa")
    spend(root, "qa", 10.0)
    assert run(root, "start", "qa") == heartbeat.STOP
    req = next(i["number"] for i in fake.issues.values() if "gate:budget" in fake.names(i["number"]))
    fake.author = "someone-else"
    fake.comments[req].append({"user": {"login": "someone-else"}, "body": "/approve"})
    assert run(root, "start", "qa") == heartbeat.STOP, "a non-founder's /approve never counts"
    fake.comments[req].append({"user": {"login": "acme"}, "body": "/approve"})
    assert run(root, "start", "qa") == heartbeat.OK, "the founder's /approve adds one more month's budget"


def test_transcript_cost_counts_each_message_once(tmp_path):
    usage = {"input_tokens": 1_000_000, "output_tokens": 100_000, "cache_read_input_tokens": 1_000_000}
    lines = [{"type": "assistant", "message": {"id": "m1", "model": "claude-sonnet-5-5", "usage": usage}}] * 3
    lines += [{"type": "assistant", "message": {"id": "m2", "model": "unknown-model", "usage": {"output_tokens": 1000}}}]
    path = tmp_path / "s.jsonl"
    path.write_text("\n".join(json.dumps(x) for x in lines) + "\nnot json\n", encoding="utf-8")
    pol = {"prices_usd_per_mtok": {"sonnet": {"input": 2, "output": 10, "cache_read": 0.1}}}
    assert heartbeat.transcript_usd(path, pol) == round(2 + 1 + 0.1 + 0.05, 4), "unknown models use the top price"
    (tmp_path / "empty.jsonl").write_text("{}\n", encoding="utf-8")
    assert heartbeat.transcript_usd(tmp_path / "empty.jsonl", pol) is None


def test_each_run_records_its_outcome_time_objective_and_session(root, fake, capsys, monkeypatch):
    n = ticket(fake, "engineer", "Build it")
    fake.issues[n]["labels"].append({"name": "goal:O1"})
    assert run(root, "start", "engineer") == heartbeat.OK
    assert heartbeat.main(["end", "engineer", "--ticket", str(n), "--usd", "1.25", "--model", "mid-tier",
                           "--session", "https://claude.ai/code/session_x", "--now", str(NOW + 600),
                           "--root", str(root), "--month", MONTH]) == heartbeat.OK
    monkeypatch.setenv("S2S_SESSION_URL", "file:///etc/passwd")
    assert run(root, "end", "engineer", "--usd", "0.25", "--outcome", "no-work") == heartbeat.OK
    with pytest.raises(SystemExit, match="--outcome"):
        run(root, "end", "engineer", "--usd", "1", "--outcome", "great")
    log = next(i for i in fake.issues.values() if "cost-log" in fake.names(i["number"]))
    first, second = heartbeat.entries(fake.comments[log["number"]], MONTH)
    assert first["outcome"] == "worked" and first["seconds"] == 600 and first["objective"] == "O1"
    assert first["session"] == "https://claude.ai/code/session_x" and first["model"] == "mid-tier"
    assert second["outcome"] == "no-work" and second["session"] == "" and second["seconds"] is None, "only https links"
    assert ", worked, 10 min" in fake.comments[log["number"]][0]["body"]
    capsys.readouterr()
    assert run(root, "runs", "--role", "engineer") == heartbeat.OK
    out = capsys.readouterr().out
    assert "| engineer | worked | #" in out and "success 100%" in out and "no-work 1" in out


def test_run_stats_and_the_forecast():
    import datetime as dt
    runs = [{"outcome": o, "usd": u, "seconds": s} for o, u, s in
            [("worked", 2.0, 60), ("failed", 1.0, 300), ("no-work", 0.5, None), ("worked", 1.5, 120)]]
    st = heartbeat.run_stats(runs)
    assert st["success"] == pytest.approx(2 / 3, abs=1e-4), "no-work runs don't count against an agent"
    assert st["median_seconds"] == 120 and st["usd_per_worked"] == 2.5 and st["outcomes"]["failed"] == 1
    assert heartbeat.run_stats([])["success"] is None
    assert heartbeat.forecast(10.0, "2026-11", dt.date(2026, 11, 10)) == 30.0
    assert heartbeat.forecast(10.0, "2026-10", dt.date(2026, 11, 10)) is None
    bad = [{"body": '<!-- s2s:cost {"role": "qa", "usd": true, "month": "2026-11"} -->'},
           {"body": '<!-- s2s:cost {"role": "qa", "usd": 1, "month": "2026-11", "outcome": "<b>", "session": "javascript:x", "seconds": -5} -->'}]
    (only,) = heartbeat.entries(bad, MONTH)
    assert only["outcome"] == "" and only["session"] == "" and only["seconds"] is None
